cd /workspace && node -e "
const XLSX = require('xlsx');
const { Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell, WidthType, BorderStyle, AlignmentType, HeadingLevel } = require('docx');
const fs = require('fs');

// Read Excel data
const wb = XLSX.readFile('testbed/data/product_inventory.xlsx');
const products = XLSX.utils.sheet_to_json(wb.Sheets['Products']);

// Compute summary stats
const totalProducts = products.length;
const categories = {};
let minPrice = Infinity, maxPrice = -Infinity;
products.forEach(p => {
  const cat = p['Category'];
  categories[cat] = (categories[cat] || 0) + 1;
  if (p['Price'] < minPrice) minPrice = p['Price'];
  if (p['Price'] > maxPrice) maxPrice = p['Price'];
});
const allInStock = products.every(p => p['In Stock'] === 'Yes');

// Build table rows
const headerCells = ['Product ID', 'Name', 'Category', 'Price', 'In Stock'].map(h =>
  new TableCell({
    children: [new Paragraph({ children: [new TextRun({ text: h, bold: true, size: 20, font: 'Calibri' })] })],
    width: { size: 20, type: WidthType.PERCENTAGE },
  })
);
const tableRows = [new TableRow({ children: headerCells, tableHeader: true })];

products.forEach(p => {
  const vals = [p['Product ID'], p['Name'], p['Category'], '\$' + p['Price'], p['In Stock']];
  const cells = vals.map(v =>
    new TableCell({
      children: [new Paragraph({ children: [new TextRun({ text: String(v), size: 20, font: 'Calibri' })] })],
      width: { size: 20, type: WidthType.PERCENTAGE },
    })
  );
  tableRows.push(new TableRow({ children: cells }));
});

// Category breakdown string
const catBreakdown = Object.entries(categories)
  .sort((a, b) => b[1] - a[1])
  .map(([c, n]) => c.charAt(0).toUpperCase() + c.slice(1) + ' (' + n + ')')
  .join(', ');

// Build document
const doc = new Document({
  sections: [{
    children: [
      new Paragraph({
        children: [new TextRun({ text: 'Product Inventory Summary', bold: true, size: 32, font: 'Calibri' })],
        heading: HeadingLevel.HEADING_1,
        alignment: AlignmentType.CENTER,
        spacing: { after: 200 },
      }),
      new Paragraph({
        children: [new TextRun({ text: 'Overview', bold: true, size: 26, font: 'Calibri' })],
        heading: HeadingLevel.HEADING_2,
        spacing: { before: 200, after: 100 },
      }),
      new Paragraph({
        children: [new TextRun({ text: 'This document provides a summary of the current product inventory. The data has been sourced from the product_inventory.xlsx file.', size: 22, font: 'Calibri' })],
        spacing: { after: 100 },
      }),
      new Paragraph({
        children: [
          new TextRun({ text: 'Total Products: ', bold: true, size: 22, font: 'Calibri' }),
          new TextRun({ text: String(totalProducts), size: 22, font: 'Calibri' }),
        ],
        spacing: { after: 50 },
      }),
      new Paragraph({
        children: [
          new TextRun({ text: 'Categories: ', bold: true, size: 22, font: 'Calibri' }),
          new TextRun({ text: catBreakdown, size: 22, font: 'Calibri' }),
        ],
        spacing: { after: 50 },
      }),
      new Paragraph({
        children: [
          new TextRun({ text: 'Price Range: ', bold: true, size: 22, font: 'Calibri' }),
          new TextRun({ text: '\$' + minPrice + ' – \$' + maxPrice, size: 22, font: 'Calibri' }),
        ],
        spacing: { after: 50 },
      }),
      new Paragraph({
        children: [
          new TextRun({ text: 'Stock Status: ', bold: true, size: 22, font: 'Calibri' }),
          new TextRun({ text: allInStock
            ? 'All ' + totalProducts + ' listed items are marked as In Stock = Yes. No out-of-stock products were found in the inventory.'
            : 'Some items are out of stock.', size: 22, font: 'Calibri' }),
        ],
        spacing: { after: 200 },
      }),
      new Paragraph({
        children: [new TextRun({ text: 'Product Details', bold: true, size: 26, font: 'Calibri' })],
        heading: HeadingLevel.HEADING_2,
        spacing: { before: 200, after: 100 },
      }),
      new Table({ rows: tableRows, width: { size: 100, type: WidthType.PERCENTAGE } }),
      new Paragraph({
        children: [new TextRun({ text: '', size: 22 })],
        spacing: { before: 200 },
      }),
      new Paragraph({
        children: [new TextRun({ text: 'Note: ', bold: true, size: 22, font: 'Calibri' }),
                   new TextRun({ text: 'This summary was auto-generated from data/product_inventory.xlsx. All products listed in the source file have their \"In Stock\" status set to \"Yes\".', size: 22, font: 'Calibri' })],
        spacing: { after: 100 },
      }),
    ],
  }],
});

// Write to file
Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync('data/inventory_summary.docx', buffer);
  console.log('Document saved: data/inventory_summary.docx');
  console.log('File size: ' + (buffer.length / 1024).toFixed(1) + ' KB');
});
"

